import { update_guest_house_details } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteguestDialog: Boolean,
    ViewInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_dailog() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_guest_house_details, {
          input: {
            guest_house_status: "DEACTIVE",
            guest_house_id: this.ViewInfo.guest_house_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.update_guest_house_details);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("error_info", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
